#include "hd20_protocol.h"
#include "vsony_host.h"
#include <string.h>
size_t hd20_encode7(const uint8_t *in,size_t n,uint8_t *o,size_t cap){size_t w=0;for(size_t i=0;i<n;i+=7){size_t k=n-i,m=k>7?7:k;uint8_t l=0;for(size_t j=0;j<m;j++){o[w++]=(uint8_t)(0x80|(in[i+j]>>1));l|=(uint8_t)((in[i+j]&1)<<j);}if(w>=cap)return 0;o[w++]=(uint8_t)(0x80|l);}return w;}
int hd20_decode7(const uint8_t *in,size_t n,uint8_t *o,size_t cap){if(n%8)return HD20_ERR_FORMAT;size_t w=0;for(size_t i=0;i<n;i+=8){uint8_t l=in[i+7]&0x7f;for(size_t j=0;j<7;j++){if(w>=cap)return HD20_ERR_FORMAT;o[w++]=(uint8_t)(((in[i+j]&0x7f)<<1)|((l>>j)&1));}}return (int)w;}
uint8_t hd20_checksum(const uint8_t *p,size_t n){uint8_t s=0;for(size_t i=0;i<n;i++)s=(uint8_t)(s+p[i]);return (uint8_t)(0-s);}
int hd20_build_status(uint8_t *o,size_t cap,uint32_t blocks){if(cap<343)return HD20_ERR_FORMAT;memset(o,0,343);o[0]=0x83;o[1]=0;o[2]=0;o[3]=0;o[4]=0;o[5]=0;o[6]=0;o[7]=0;o[8]=0;o[9]=1;o[10]=0xE2;o[11]=(uint8_t)(blocks>>16);o[12]=(uint8_t)(blocks>>8);o[13]=(uint8_t)blocks;o[342]=hd20_checksum(o,342);return 343;}
int hd20_process_command(const uint8_t *c,size_t n,struct vsony_host*d,uint8_t*r,size_t cap,size_t*rn){if(!c||!d||!r||!rn||n<2)return HD20_ERR_FORMAT;*rn=0;if(c[0]!=HD20_SYNC_READ&&c[0]!=HD20_SYNC_WRITE)return HD20_ERR_FORMAT;uint8_t op=c[1];if(op==HD20_CMD_STATUS){if(n<7)return HD20_ERR_FORMAT;int z=hd20_build_status(r,cap,(uint32_t)(vsony_size(d)/HD20_BLOCK_SIZE));if(z<0)return z;*rn=(size_t)z;return 0;}if(op!=HD20_CMD_READ&&op!=HD20_CMD_WRITE&&op!=HD20_CMD_WRITE_VERIFY)return HD20_ERR_FORMAT;if(n<7)return HD20_ERR_FORMAT;uint8_t seq=c[2];uint32_t block=((uint32_t)c[3]<<16)|((uint32_t)c[4]<<8)|c[5];if(((uint64_t)block+1)*HD20_BLOCK_SIZE>vsony_size(d))return HD20_ERR_RANGE;if(op==HD20_CMD_READ){size_t need=539;if(cap<need)return HD20_ERR_FORMAT;memset(r,0,need);r[0]=0x80;r[1]=seq;r[2]=0;r[3]=0;r[4]=0;r[5]=0;if(vsony_read(d,(uint64_t)block*HD20_BLOCK_SIZE,r+26,HD20_BLOCK_SIZE))return HD20_ERR_IO;r[538]=hd20_checksum(r,538);*rn=need;return 0;}if(n<7+532)return HD20_ERR_FORMAT;const uint8_t*q=c+7;if(q[0]!=HD20_SYNC_WRITE||q[1]!=0x01)return HD20_ERR_FORMAT;if(vsony_write(d,(uint64_t)block*HD20_BLOCK_SIZE,q+20,HD20_BLOCK_SIZE))return HD20_ERR_IO;r[0]=0x81;r[1]=seq;r[2]=0;r[3]=0;r[4]=0;r[5]=0;r[6]=0;r[7]=hd20_checksum(r,7);*rn=8;return 0;}
